<form method="POST" action="{{ $article ? route('saas-ops.knowledge-base.update',$article) : route('saas-ops.knowledge-base.store') }}" class="rounded-xl border bg-white p-5 dark:border-slate-800 dark:bg-slate-900">@csrf @if($article) @method('PUT') @endif<div class="grid gap-4 md:grid-cols-2"><input name="title" value="{{ old('title',$article?->title) }}" placeholder="title" class="rounded-lg dark:bg-slate-950"><input name="category" value="{{ old('category',$article?->category ?? 'general') }}" class="rounded-lg dark:bg-slate-950"><select name="visibility" class="rounded-lg dark:bg-slate-950">@foreach(['internal','school','public'] as $visibility)<option value="{{ $visibility }}" @selected(old('visibility',$article?->visibility ?? 'internal')===$visibility)>{{ $visibility }}</option>@endforeach</select><select name="status" class="rounded-lg dark:bg-slate-950"><option value="draft" @selected(old('status',$article?->status ?? 'draft')==='draft')>draft</option><option value="published" @selected(old('status',$article?->status)==='published')>published</option></select></div><textarea name="body" class="mt-3 w-full rounded-lg dark:bg-slate-950" placeholder="body">{{ old('body',$article?->body) }}</textarea><button class="mt-3 rounded-lg bg-lime-500 px-4 py-2 text-sm font-black text-white">Simpan</button></form>
